insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_152'
from (values
('127.923.d.1.A',3,'An intern at a print shop notices jobs keep piling up at the folding machine, so she breaks down each step and proposes a new order for the workflow. She is:','["analyzing elements of a problem to develop creative and innovative solutions", "waiting for the pile to disappear", "blaming the machine", "avoiding the folding station"]'::jsonb,0,'Creative solutions.','original'),
('127.923.d.1.A',4,'Why does separating a problem into elements often lead to better solutions?','["It hides the real cause", "Each element can be examined and improved", "It makes the problem larger", "It removes the need for ideas"]'::jsonb,1,'Analysis.','original'),
('127.923.d.1.B',3,'An intern finds five articles on reducing waste and keeps only the two that match her shop''s materials and equipment. She is:','["choosing at random", "keeping every article", "critically analyzing information to determine its relevance to the problem-solving process", "ignoring the topic"]'::jsonb,2,'Relevance.','original'),
('127.923.d.1.B',4,'Which question best tests whether information is relevant to a problem?','["Is it the first result?", "Is it the longest document?", "Is it written in bold?", "Does this directly help solve what we are facing?"]'::jsonb,3,'Relevance test.','original'),
('127.923.d.1.C',3,'An intern lists the cost, speed and risk of buying a new tool versus repairing the old one and uses a decision chart to choose. She is:','["comparing and contrasting alternatives using problem-solving and critical-thinking skills", "ignoring the options", "flipping a coin", "choosing the cheapest without looking"]'::jsonb,0,'Compare options.','original'),
('127.923.d.1.C',4,'A decision chart that scores each option on several criteria is useful because it:','["removes the need to decide", "makes the trade-offs between choices visible", "picks a winner at random", "hides the criteria"]'::jsonb,1,'Decision chart.','original'),
('127.923.d.1.D',3,'An intern reads the equipment manual, checks a safety data sheet and calls a vendor before choosing a cleaning product. She is:','["guessing which product is best", "skipping the manual", "conducting technical research to gather information necessary for decision making", "choosing by label color"]'::jsonb,2,'Technical research.','original'),
('127.923.d.1.D',4,'Which source is best for technical research about a machine''s settings?','["A rumor from a coworker", "A hunch", "An unsigned post online", "The manufacturer''s official manual"]'::jsonb,3,'Best source.','original'),
('127.923.d.2.A',3,'An intern studies how respected team leaders show trust, stay positive during setbacks and give clear direction. She is:','["analyzing leadership characteristics related to trusting others and maintaining a positive attitude", "copying a bad example", "avoiding the team", "ignoring leaders"]'::jsonb,0,'Leadership.','original'),
('127.923.d.2.A',4,'A leader who trusts the team usually:','["hides the plan", "delegates tasks and lets people do them", "checks every small step", "takes every job"]'::jsonb,1,'Trust.','original'),
('127.923.d.2.B',3,'Three interns assemble a display by splitting the work, passing materials to each other and finishing together. They are:','["arguing about roles", "working separately with no plan", "demonstrating teamwork skills through working cooperatively to achieve goals", "competing for credit"]'::jsonb,2,'Teamwork.','original'),
('127.923.d.2.B',4,'Which behavior best supports teamwork?','["Keeping useful tips private", "Taking credit for group work", "Doing only your own part and nothing else", "Sharing information that the whole group needs"]'::jsonb,3,'Support team.','original'),
('127.923.d.2.C',3,'After a project, a team holds a quick review where members suggest fixes, agree on two changes and plan to try them next time. They are:','["demonstrating teamwork processes that promote team building, consensus and continuous improvement", "ignoring the review", "blaming one member", "ending the discussion early"]'::jsonb,0,'Team process.','original'),
('127.923.d.2.C',4,'Continuous improvement means a team:','["never changes its methods", "keeps looking for ways to do the work better", "only fixes problems after failure", "avoids feedback"]'::jsonb,1,'Improvement.','original'),
('127.923.d.2.D',3,'An intern is asked to order supplies for the team and to also finish her own report, and she completes both on schedule. She is:','["forgetting the order", "handing the job off", "demonstrating responsibility for group and individual work tasks", "skipping her own report"]'::jsonb,2,'Responsibility.','original'),
('127.923.d.2.D',4,'If a shared task is falling behind, a responsible team member:','["hides the problem", "blames a teammate", "waits for someone else", "speaks up and helps get it back on track"]'::jsonb,3,'Responsible member.','original'),
('127.923.d.2.E',3,'An intern thanks a mentor, keeps her commitments and offers to help a busy coworker so the department works well together. She is:','["establishing and maintaining effective working relationships in order to accomplish objectives", "taking help without giving it", "breaking promises", "avoiding contact"]'::jsonb,0,'Working relationships.','original'),
('127.923.d.2.E',4,'Good working relationships help a team to:','["avoid goals", "reach its objectives more smoothly", "lose time", "create conflict"]'::jsonb,1,'Objectives.','original'),
('127.923.d.2.F',3,'An intern disagrees with a plan, so she asks to talk privately, states her concern calmly and listens to the answer. She is:','["complaining to others", "saying nothing and resenting it", "demonstrating effective working relationships using interpersonal skills", "shouting in public"]'::jsonb,2,'Interpersonal skills.','original'),
('127.923.d.2.F',4,'The best time to raise a concern with a coworker is usually:','["in front of customers", "never", "while angry", "at a calm moment, in a respectful way"]'::jsonb,3,'Raise concerns.','original'),
('127.923.d.2.G',3,'An intern greets everyone by name, holds a door for a delivery driver and says thanks when a teammate covers for her. She is:','["using positive interpersonal skills to work cooperatively with others", "complaining", "ignoring people", "taking help for granted"]'::jsonb,0,'Positive skills.','original'),
('127.923.d.2.G',4,'Which action shows positive interpersonal skills?','["Rolling your eyes at ideas", "Giving sincere appreciation to a coworker", "Gossiping about a teammate", "Interrupting others"]'::jsonb,1,'Appreciation.','original'),
('127.923.d.2.H',3,'Two interns both need the only laptop on Friday, so they discuss their deadlines and agree to split the time. They are:','["taking it without asking", "arguing until one gives up", "negotiating effectively to arrive at decisions", "avoiding the issue"]'::jsonb,2,'Negotiation.','original'),
('127.923.d.2.H',4,'Effective negotiation begins with:','["staying silent", "demanding your way", "refusing to talk", "understanding what each side needs"]'::jsonb,3,'Negotiation start.','original'),
('127.923.d.2.I',3,'An intern learns the customs and holidays of a coworker''s culture and makes sure meetings do not fall on an important day. She is:','["demonstrating respect for individuals, including those from different cultures, genders and religions", "ignoring differences", "excluding the coworker", "making jokes about them"]'::jsonb,0,'Respect.','original'),
('127.923.d.2.I',4,'Respect for different backgrounds in the workplace helps because it:','["divides the team", "lets every person contribute and feel valued", "limits who may speak", "wastes time"]'::jsonb,1,'Respect value.','original'),
('127.923.d.2.J',3,'A manager invites quiet voices to share ideas and treats views from all backgrounds as valuable. She is:','["ignoring some ideas", "shutting down discussion", "demonstrating sensitivity to and value for diversity", "favoring one group"]'::jsonb,2,'Diversity.','original'),
('127.923.d.2.J',4,'Valuing diversity on a team helps by:','["excluding viewpoints", "making people agree on everything", "lowering creativity", "bringing in a wider range of ideas and experience"]'::jsonb,3,'Wider ideas.','original'),
('127.923.d.3.A',3,'An intern calls a tool a ''micrometer'' and not ''the measuring thing'' while explaining a measurement to a client. She is:','["demonstrating the use of content, technical concepts and vocabulary when analyzing information", "using vague words", "avoiding the topic", "making up names"]'::jsonb,0,'Vocabulary.','original'),
('127.923.d.3.A',4,'Technical vocabulary is most useful when workers:','["want to sound important", "need to share exact meaning quickly", "skip details", "avoid being understood"]'::jsonb,1,'Exact meaning.','original'),
('127.923.d.3.B',3,'An intern asks a customer three direct questions about a delivery problem and then summarizes the answer back to her manager. She is:','["mumbling the summary", "guessing the problem", "employing verbal skills when obtaining and conveying information", "avoiding the customer"]'::jsonb,2,'Verbal skills.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_152'
from (values
('127.923.d.3.B',4,'A strong way to convey information verbally is to:','["use only slang", "avoid eye contact", "speak fast and leave", "speak clearly and check that the listener understood"]'::jsonb,3,'Convey.','original'),
('127.923.d.3.C',3,'An intern reads a manufacturer''s website and a technical guide to review how a new scheduling tool works before she sets it up. She is:','["using informational texts, Internet websites and technical materials to review and implement a procedure", "asking no one", "guessing the setup", "skipping the guide"]'::jsonb,0,'Reading.','original'),
('127.923.d.3.C',4,'After reading a procedure in a technical guide, a worker should:','["change the order", "follow the steps in order and confirm each one", "do the steps from memory", "skip the hard ones"]'::jsonb,1,'Follow steps.','original'),
('127.923.d.3.D',3,'An intern notices that a blog post about a repair has no author, no date and no sources, so she checks the manufacturer''s page instead. She is:','["trusting the blog", "ignoring the issue", "evaluating the reliability of information from informational texts, Internet websites and technical materials", "copying it directly"]'::jsonb,2,'Reliability.','original'),
('127.923.d.3.D',4,'A sign that a source may be unreliable is that it:','["lists its sources", "cites official standards", "is from a recognized organization", "gives no author, date or evidence"]'::jsonb,3,'Unreliable sign.','original'),
('127.923.d.3.E',3,'An intern sees a client sigh and check his watch during an explanation, so she shortens her answer and offers a summary. She is:','["interpreting verbal and nonverbal cues or behaviors to enhance communication", "ignoring the client", "getting upset", "talking longer"]'::jsonb,0,'Cues.','original'),
('127.923.d.3.E',4,'Which is a nonverbal cue?','["A spoken sentence", "A person''s posture or facial expression", "The words in an email", "A printed rule"]'::jsonb,1,'Nonverbal.','original'),
('127.923.d.3.F',3,'An intern puts her phone away, makes eye contact and says, ''So the deadline moved to Thursday?'' to confirm what her supervisor said. She is:','["texting during the meeting", "interrupting the supervisor", "applying active listening skills to obtain and clarify information", "assuming she knew the answer"]'::jsonb,2,'Active listening.','original'),
('127.923.d.3.F',4,'Active listening helps prevent:','["accurate notes", "good teamwork", "clear communication", "mistakes caused by misunderstanding"]'::jsonb,3,'Prevents mistakes.','original'),
('127.923.d.3.G',3,'An intern writes a clear email with a short subject line and then explains the same point aloud at the weekly meeting. She is:','["using academic skills to facilitate effective written and oral communication", "avoiding both writing and speaking", "using only slang", "leaving details out"]'::jsonb,0,'Academic skills.','original'),
('127.923.d.3.G',4,'Strong grammar and organization in a work email help the reader to:','["miss the main point", "understand the message quickly", "feel confused", "ask for more drafts"]'::jsonb,1,'Writing.','original'),
('127.923.d.4.A',3,'An intern in a final-year placement takes on harder tasks in her chosen field, with a mentor reviewing each step. She is:','["avoiding her field", "repeating only beginner tasks", "developing advanced technical knowledge and skills related to her personal career goal", "changing goals daily"]'::jsonb,2,'Advanced.','original'),
('127.923.d.4.A',4,'A personal career goal can guide a student''s practicum by:','["making tasks random", "avoiding feedback", "limiting all learning", "helping her choose tasks that build relevant skills"]'::jsonb,3,'Goal guide.','original'),
('127.923.d.4.B',3,'An intern and her supervisor rate her skills on a form: strong in scheduling, needs work on budgeting. They are:','["evaluating technical skill proficiencies", "guessing her level", "ignoring the results", "praising only"]'::jsonb,0,'Evaluate skills.','original'),
('127.923.d.4.B',4,'The main purpose of evaluating technical skill proficiency is to:','["avoid training", "find out what to practice or improve next", "assign blame", "hide weak areas"]'::jsonb,1,'Purpose.','original'),
('127.923.d.4.C',3,'An intern''s supervisor says her reports are too long, and she asks for an example and rewrites the next one. She is:','["defending the old reports", "ignoring the note", "accepting critical feedback provided by the supervisor", "complaining about the supervisor"]'::jsonb,2,'Take feedback.','original'),
('127.923.d.4.C',4,'Which response to critical feedback is most productive?','["Stay silent and change nothing", "Blame another coworker", "Argue every point", "Ask clarifying questions and apply the suggestions"]'::jsonb,3,'Productive response.','original'),
('127.923.d.5.B',3,'At a school expo, an intern walks local employers through her portfolio and answers their questions. She is:','["presenting the portfolio to interested stakeholders", "refusing questions", "avoiding the employers", "leaving the portfolio at home"]'::jsonb,0,'Present.','original'),
('127.923.d.5.B',4,'A student who prepares to present her portfolio should:','["skip the practice", "practice explaining each item and its purpose", "hide weak samples", "read it word for word"]'::jsonb,1,'Prepare.','original'),
('127.923.d.5.A.i',3,'An intern adds the certifications and competency checklists she earned this term to her portfolio. She is:','["copying someone else''s", "leaving the portfolio blank", "updating a professional portfolio to include attainment of technical skill competencies", "removing her records"]'::jsonb,2,'Skill attainment.','original'),
('127.923.d.5.A.i',4,'Which item shows attainment of a technical skill competency?','["A blank form", "A lunch menu", "A class schedule only", "A signed competency checklist"]'::jsonb,3,'Competency evidence.','original'),
('127.923.d.5.A.ii',3,'An intern adds notes about a job shadow and a summer workshop to her portfolio. She is:','["updating a professional portfolio to include extended learning experiences", "deleting the notes", "guessing the dates", "leaving out her experiences"]'::jsonb,0,'Extended learning.','original'),
('127.923.d.5.A.ii',4,'A workshop outside of class could be listed in a portfolio as:','["a lunch order", "an extended learning experience", "a grade report", "a disciplinary note"]'::jsonb,1,'Extended.','original'),
('127.923.d.5.A.iii',3,'An intern writes a one-paragraph abstract of the technical writing she completed and puts it in her portfolio. She is:','["skipping technical writing", "copying a textbook", "updating a professional portfolio to include an abstract of technical writing", "leaving out her work"]'::jsonb,2,'Abstract.','original'),
('127.923.d.5.A.iii',4,'An abstract of technical writing is best described as:','["a table of prices", "a list of names", "the full document", "a short summary of the main points of the work"]'::jsonb,3,'Abstract def.','original'),
('127.923.d.5.A.iv',3,'An intern revises her resume to list her new skills and attaches it to her portfolio. She is:','["updating a professional portfolio to include a resume", "deleting it", "leaving the old one", "using a template without changes"]'::jsonb,0,'Resume.','original'),
('127.923.d.5.A.iv',4,'A hiring manager flips to the resume page of a student portfolio. Which version makes the best impression?','["One packed with unrelated details", "One that is current, accurate and easy to scan", "One with several typos", "One that is three years old"]'::jsonb,1,'A strong resume is current and clear.','original'),
('127.923.d.5.A.v',3,'An intern includes a flyer she designed, a photo of a display she built and a short report as examples of her work. She is:','["leaving it empty", "throwing away her projects", "updating a professional portfolio to include samples of work", "using strangers'' work"]'::jsonb,2,'Samples.','original'),
('127.923.d.5.A.v',4,'Samples of work show employers:','["her favorite colors", "her schedule", "her lunch choices", "what the student can actually produce"]'::jsonb,3,'Show ability.','original'),
('127.923.d.5.A.vi',3,'An intern places her supervisor''s signed evaluation of her performance in her portfolio. She is:','["updating a professional portfolio to include an evaluation from a supervisor", "leaving it out", "removing feedback", "hiding results"]'::jsonb,0,'Evaluation.','original'),
('127.923.d.5.A.vi',4,'Why would an employer value a supervisor''s evaluation in a portfolio?','["It replaces an interview", "It gives an outside view of the student''s performance", "It lists the pay rate", "It shows the student''s schedule"]'::jsonb,1,'Outside view.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
